    data["title"] = "3-Ⅳ-4：從標題、軸線、刻度與資料變化理解簡易圖表"
    data["content"] = {"summary": "圖表不是把數字換成英文就完成閱讀；要先讀標題、欄列或橫縱軸、單位與刻度，再依問題比較最高最低、早晚、相等與變化，最後用不超過資料的句子描述趨勢。本課以借書量、訪客數、溫度、回收公斤數、點心調查、公車時間、閱讀量、長條刻度、折線變化與活動時間表等原創資料，練習把表格和圖形轉成準確英文回答，並區分資料直接支持的結論與需要平均、原因或額外計算才可提出的推論。", "sections": [{"heading": "先讀圖表的身份和單位", "body": "Books Borrowed in April 加上 Number of books 的縱軸，說明圖表量的是四月借書本數；標題、軸線與單位先決定每個數字代表什麼。若直接比較高度而沒看刻度或欄位，可能把溫度、公斤和人數混為一談。"}, {"heading": "最高最低要逐格比較", "body": "Monday 12、Tuesday 18、Wednesday 15 中，18 是最高；24°C、21°C、27°C、23°C 中，21°C 是最低或 coolest。先把問題的比較詞圈起來，再逐格讀數字，不能用日期順序或柱子顏色猜答案。"}, {"heading": "刻度決定數量換算", "body": "每條格線代表 10 visitors，第三條格線就是 30 visitors，不是 3 或 10。讀長條圖時先找零點、每格單位與柱頂位置；若柱頂落在兩格之間，要保留估計或回查圖例，不假裝有精確數字。"}, {"heading": "趨勢描述要保留範圍", "body": "折線從一月升到三月、四月下降，只能說這段期間先增加後減少；沒有控制條件或原因資料時，不能說某政策造成變化。活動時間表則是安排，不是數量趨勢；回答時先判斷資料型態，再選 compare、increase、decrease、equal 或 schedule。"}]}
    data["studyHighlights"] = ["先讀標題、軸線、欄位、單位與刻度，再解讀數字。", "以最高、最低、早晚、相等與差異問題逐格比較資料。", "依圖例和每格單位換算長條高度，不把格線當成單純數字。", "用有範圍的語句描述趨勢，避免把相關變化當成原因。"]
    data["teaching"] = {"body": [{"id": "hook", "phase": "hook", "heading": "看最高的柱子就一定知道答案嗎？", "body": "展示完全自編的訪客長條圖，一張沒有標題和單位，一張補上 Number of visitors、每格 10 人與日期。學生先各自回答，再比較答案差異，從錯誤中發現圖表身份和刻度比柱子外觀更先需要讀。"}, {"id": "explain", "phase": "explain", "heading": "圖表七欄讀取卡", "body": "建立 Title、Categories、Axis or columns、Unit、Scale、Comparison、Change／limit 七欄。先用標題和軸線翻譯資料身份，再標單位與格線，最後回答問題要求的比較或趨勢；沒有原因欄時不自行補因果。"}, {"id": "worked-example", "phase": "worked-example", "heading": "從格線讀出 30 位訪客", "body": "以 each grid line represents 10 visitors、bar reaches the third grid line 示範：先找每格單位，再計算 10+10+10，得到 30。比較若只回答 third line，說明那是位置不是資料量；若圖表沒有零點，先標示需要更多圖例。"}, {"id": "guided-practice", "phase": "guided-practice", "heading": "同一資料換成不同問題", "body": "給出借閱、溫度、回收、點心、公車和活動時間表六組原創圖表。學生先各自寫 highest、coolest、earlier、equal 或 schedule 問題，再交換回答；同伴必須指出標題、欄位、單位或刻度的證據，不能只說柱子比較高。"}, {"id": "transfer", "phase": "transfer", "heading": "把圖表結論寫成不過度的摘要", "body": "輪換折線上升下降、學生閱讀量與活動排程。學生寫一句資料直接支持的結論，再寫一句不能由圖表單獨證明的原因或平均問題；將 first／then、more／less、earlier／later 與 between 等詞連回資料範圍。"}, {"id": "reflect", "phase": "reflect", "heading": "我讀的是資料還是圖形印象？", "body": "回看答案，標記 title／unit 錯誤、scale 錯誤、比較錯誤、趨勢超出範圍或因果過度推論。修訂時回到原始欄位與數字，若圖表沒有支持原因、平均或個體差異，就把句子改成描述而非解釋。"}], "summary": ["以 Title、Categories、Axis、Unit、Scale、Comparison、Change／limit 七欄讀圖表。", "先判斷資料身份與刻度，再回答最高最低、早晚與相等。", "用格線單位和圖例換算，不把位置誤當數量。", "以有範圍的描述區分圖表直接證據和額外推論。"], "exitCheck": [{"prompt": "讀圖表的第一步為什麼不是直接比較柱子？", "expectedEvidence": "能先找標題、軸線、欄位、單位與刻度，確認數字代表的資料。"}, {"prompt": "如何從每格 10 人的第三條格線得到數量？", "expectedEvidence": "能將每格單位與格線位置相乘，說明第三格代表 30 而不是 3 或 10。"}, {"prompt": "折線先升後降時可以提出什麼結論？", "expectedEvidence": "能描述指定期間的增加與減少，但不把沒有資料支持的原因或因果當成確定結論。"}]}
    data["interactive"] = {"type": "guided-choice", "goal": "從圖表標題、欄位、軸線、單位、刻度與變化，提出符合資料範圍的英文結論。", "scenario": "學生擔任校園資料小編，要讀借閱、天氣、回收、公車與活動時間表，替不同讀者寫出準確的圖表摘要。", "variables": [{"symbol": "i", "meaning": "標題、軸線、欄位、單位與刻度"}, {"symbol": "c", "meaning": "最高、最低、早晚、相等與資料差異"}, {"symbol": "t", "meaning": "趨勢、排程、範圍與推論界線"}], "steps": [{"id": "step-1", "prompt": "A table lists Monday 12, Tuesday 18, and Wednesday 15 visitors. Which day has the highest number?", "options": ["Tuesday has the highest number, with 18 visitors.", "Monday has the highest number, with 12 visitors.", "Wednesday is the earliest day, so it has the highest number."], "answer": "A", "feedback": "A compares the values directly and reports the matching day and unit."}, {"id": "step-2", "prompt": "Each grid line represents 10 visitors. A bar reaches the third grid line. How many visitors does it represent?", "options": ["It represents 30 visitors.", "It represents 3 visitors.", "It represents 10 visitors because the bar is one object."], "answer": "A", "feedback": "Three intervals of 10 visitors give 30; the grid scale must be used rather than the bar count."}, {"id": "step-3", "prompt": "A line chart rises from January to March and then falls in April. Which statement is careful?", "options": ["The value increased through March and then decreased in April.", "A new rule definitely caused the increase.", "The value stayed exactly the same all year."], "answer": "A", "feedback": "A describes the visible trend and its time range without inventing a cause or ignoring the fall."}]}
